#!/usr/bin/env bash
# Exact ownership receipt MTR0fa2fc8f9d. No DDL, FK disabling or broad deletion.
set -euo pipefail
[[ "$(hostname)" = vm-ubuntu-go-dev ]]
[[ "$(id -u)" = 0 ]]
mysql --batch --skip-column-names element <<'SQL'
SET NAMES utf8mb4;
SET SESSION SQL_SAFE_UPDATES=1;
SET SESSION group_concat_max_len=1048576;
START TRANSACTION;
SELECT id FROM el_exam WHERE id IN ('1791035454578278939','1791035454665966580','1791035454747656245','1791035454815632967') ORDER BY id FOR UPDATE;
SELECT id FROM el_mng_definition_bundle WHERE id IN ('e0755b0a-5e59-4ed8-9ea0-b91212cedf01','f2d92e1f-d44e-4b40-ad96-6601e2ef85b4') ORDER BY id FOR UPDATE;
SELECT exam_id FROM el_mng_exam_profile WHERE exam_id IN ('1791035454578278939','1791035454665966580','1791035454747656245','1791035454815632967') ORDER BY exam_id FOR UPDATE;
SELECT id FROM el_paper WHERE id='4db1d50d-e295-4e7d-8e57-28bd6ee32aae' FOR UPDATE;
SELECT IF((SELECT COUNT(*) FROM el_exam WHERE
 (id='1791035454578278939' AND title='MTR0fa2fc8f9d-00201-candidate') OR
 (id='1791035454665966580' AND title='MTR0fa2fc8f9d-00201-tester') OR
 (id='1791035454747656245' AND title='MTR0fa2fc8f9d-00202-candidate') OR
 (id='1791035454815632967' AND title='MTR0fa2fc8f9d-00202-tester'))=4,1,JSON_EXTRACT('OWNERSHIP_EXAM_MISMATCH','$'));
SELECT IF((SELECT COUNT(*) FROM el_mng_exam_profile WHERE bundle_id IN ('e0755b0a-5e59-4ed8-9ea0-b91212cedf01','f2d92e1f-d44e-4b40-ad96-6601e2ef85b4'))=4 AND
 (SELECT COUNT(*) FROM el_mng_exam_profile WHERE exam_id IN ('1791035454578278939','1791035454665966580','1791035454747656245','1791035454815632967'))=4,1,JSON_EXTRACT('SHARED_BUNDLE_REFERENCE_STOP','$'));
SELECT IF((SELECT COUNT(*) FROM el_paper WHERE exam_id IN ('1791035454578278939','1791035454665966580','1791035454747656245','1791035454815632967'))=1 AND
 (SELECT COUNT(*) FROM el_paper WHERE id='4db1d50d-e295-4e7d-8e57-28bd6ee32aae' AND exam_id='1791035454578278939' AND user_id='4873ff14-4509-4101-b7ed-9e5f2334e03d')=1,1,JSON_EXTRACT('OWNERSHIP_PAPER_MISMATCH','$'));
SELECT IF((SELECT COUNT(*) FROM el_candidate WHERE exam_id IN ('1791035454578278939','1791035454665966580','1791035454747656245','1791035454815632967'))=1 AND
 (SELECT COUNT(*) FROM el_candidate WHERE id='4873ff14-4509-4101-b7ed-9e5f2334e03d' AND exam_id='1791035454578278939' AND paper_id='4db1d50d-e295-4e7d-8e57-28bd6ee32aae')=1 AND
 (SELECT COUNT(*) FROM el_tester WHERE exam_id IN ('1791035454578278939','1791035454665966580','1791035454747656245','1791035454815632967'))=2 AND
 (SELECT COUNT(*) FROM el_tester WHERE (id='1791035468793800801' AND exam_id='1791035454665966580' AND paper_id IS NULL) OR (id='1791035469458243394' AND exam_id='1791035454815632967' AND paper_id IS NULL))=2,1,JSON_EXTRACT('OWNERSHIP_PARTICIPANT_MISMATCH','$'));
SELECT IF((SELECT COUNT(*) FROM el_mng_result_run WHERE paper_id='4db1d50d-e295-4e7d-8e57-28bd6ee32aae')=0 AND
 (SELECT COUNT(*) FROM el_mng_report_current WHERE paper_id='4db1d50d-e295-4e7d-8e57-28bd6ee32aae')=0 AND
 (SELECT COUNT(*) FROM el_mng_report_revision WHERE paper_id='4db1d50d-e295-4e7d-8e57-28bd6ee32aae')=0 AND
 (SELECT COUNT(*) FROM el_mng_paper_snapshot WHERE bundle_id IN ('e0755b0a-5e59-4ed8-9ea0-b91212cedf01','f2d92e1f-d44e-4b40-ad96-6601e2ef85b4'))=1 AND
 (SELECT COUNT(*) FROM el_exam_depart WHERE exam_id IN ('1791035454578278939','1791035454665966580','1791035454747656245','1791035454815632967'))=0,1,JSON_EXTRACT('UNEXPECTED_NEW_DEPENDENCY_STOP','$'));
SELECT GROUP_CONCAT(QUOTE(id)),COUNT(*) INTO @question_ids,@question_count FROM el_mng_paper_question_snapshot WHERE paper_id='4db1d50d-e295-4e7d-8e57-28bd6ee32aae';
SELECT GROUP_CONCAT(QUOTE(id)),COUNT(*) INTO @bucket_ids,@bucket_count FROM el_paper_qu_answer WHERE paper_id='4db1d50d-e295-4e7d-8e57-28bd6ee32aae';
SELECT GROUP_CONCAT(QUOTE(id)),COUNT(*) INTO @pq_ids,@pq_count FROM el_paper_qu WHERE paper_id='4db1d50d-e295-4e7d-8e57-28bd6ee32aae';
SELECT GROUP_CONCAT(QUOTE(id)),COUNT(*) INTO @link_ids,@link_count FROM el_exam_repo WHERE exam_id IN ('1791035454578278939','1791035454665966580','1791035454747656245','1791035454815632967');
SELECT IF(@question_count=140 AND @bucket_count=700 AND @pq_count=140 AND @link_count=4,1,JSON_EXTRACT('OWNERSHIP_CARDINALITY_STOP','$'));
SELECT 'OWNED_DELETE_COUNTS',@question_count,@bucket_count,@pq_count,@link_count;
SET @sql=CONCAT('DELETE FROM el_mng_paper_question_snapshot WHERE id IN (',@question_ids,')'); PREPARE owned_stmt FROM @sql; EXECUTE owned_stmt; DEALLOCATE PREPARE owned_stmt;
DELETE FROM el_mng_paper_snapshot WHERE paper_id='4db1d50d-e295-4e7d-8e57-28bd6ee32aae';
SET @sql=CONCAT('DELETE FROM el_paper_qu_answer WHERE id IN (',@bucket_ids,')'); PREPARE owned_stmt FROM @sql; EXECUTE owned_stmt; DEALLOCATE PREPARE owned_stmt;
SET @sql=CONCAT('DELETE FROM el_paper_qu WHERE id IN (',@pq_ids,')'); PREPARE owned_stmt FROM @sql; EXECUTE owned_stmt; DEALLOCATE PREPARE owned_stmt;
DELETE FROM el_candidate WHERE id='4873ff14-4509-4101-b7ed-9e5f2334e03d';
DELETE FROM el_tester WHERE id IN ('1791035468793800801','1791035469458243394');
DELETE FROM el_paper WHERE id='4db1d50d-e295-4e7d-8e57-28bd6ee32aae';
DELETE FROM el_mng_exam_profile WHERE exam_id IN ('1791035454578278939','1791035454665966580','1791035454747656245','1791035454815632967');
DELETE FROM el_mng_definition_bundle WHERE id IN ('e0755b0a-5e59-4ed8-9ea0-b91212cedf01','f2d92e1f-d44e-4b40-ad96-6601e2ef85b4');
SET @sql=CONCAT('DELETE FROM el_exam_repo WHERE id IN (',@link_ids,')'); PREPARE owned_stmt FROM @sql; EXECUTE owned_stmt; DEALLOCATE PREPARE owned_stmt;
DELETE FROM el_exam WHERE id IN ('1791035454578278939','1791035454665966580','1791035454747656245','1791035454815632967');
COMMIT;
SELECT 'OWNED_RESIDUAL',
 (SELECT COUNT(*) FROM el_exam WHERE id IN ('1791035454578278939','1791035454665966580','1791035454747656245','1791035454815632967'))+
 (SELECT COUNT(*) FROM el_exam_repo WHERE exam_id IN ('1791035454578278939','1791035454665966580','1791035454747656245','1791035454815632967'))+
 (SELECT COUNT(*) FROM el_paper WHERE id='4db1d50d-e295-4e7d-8e57-28bd6ee32aae')+
 (SELECT COUNT(*) FROM el_paper_qu WHERE paper_id='4db1d50d-e295-4e7d-8e57-28bd6ee32aae')+
 (SELECT COUNT(*) FROM el_paper_qu_answer WHERE paper_id='4db1d50d-e295-4e7d-8e57-28bd6ee32aae')+
 (SELECT COUNT(*) FROM el_candidate WHERE id='4873ff14-4509-4101-b7ed-9e5f2334e03d')+
 (SELECT COUNT(*) FROM el_tester WHERE id IN ('1791035468793800801','1791035469458243394'));
SELECT 'EXACT_CLEANUP_COMMITTED';
SQL